import React, { useState, useEffect } from 'react';

const Map = () => {
    const [map, setMap] = useState(null);
    const [directionsService, setDirectionsService] = useState(null);
    const [directionsRenderer, setDirectionsRenderer] = useState(null);

    useEffect(() => {
        // פונקציה לאתחול המפה
        function initMap() {
            // מיקום התחלתי כפר ירכא
            const kafrYirka = { lat: 32.9533, lng: 35.2176 };

            // יצירת אובייקט מפה
            const newMap = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: kafrYirka
            });

            // הוספת סימון למפה
            new window.google.maps.Marker({
                position: kafrYirka,
                map: newMap
            });

            // יצירת אובייקטים לשירות הניווט והצגתו
            const newDirectionsService = new window.google.maps.DirectionsService();
            const newDirectionsRenderer = new window.google.maps.DirectionsRenderer();
            newDirectionsRenderer.setMap(newMap);

            setMap(newMap);
            setDirectionsService(newDirectionsService);
            setDirectionsRenderer(newDirectionsRenderer);
        }

        // טעינת ספריית Google Maps
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=AIzaSyAyCujJ188OdhtBjKLmV2CheQgDnqEa-9o&callback=initMap`;
        script.async = true;
        script.defer = true;
        script.onload = initMap; // קריאה לפונקציה initMap כאשר הסקריפט נטען
        document.head.appendChild(script);

        // ניקוי הסקריפט בזמן פירוק הקומפוננטה
        return () => {
            document.head.removeChild(script);
        };
    }, []);

    const changeView = () => {
        if (map) {
            const kafrYirka = { lat: 32.9533, lng: 35.2176 };
            map.setZoom(12);
            map.setCenter(kafrYirka);
        }
    };

    const calculateRoute = () => {
        if (directionsService && directionsRenderer) {
            const request = {
                origin: { lat: 32.9533, lng: 35.2176 }, // נקודת מוצא (כפר ירכא)
                destination: { lat: 32.0853, lng: 34.7818 }, // נקודת יעד (תל אביב לדוגמה)
                travelMode: window.google.maps.TravelMode.DRIVING
            };

            directionsService.route(request, (result, status) => {
                if (status === window.google.maps.DirectionsStatus.OK) {
                    directionsRenderer.setDirections(result);
                } else {
                    console.error(`Directions request failed due to ${status}`);
                }
            });
        }
    };

    return (
        <div className="container">
            <div className="header">Google Map Navigation</div>
            <div className="buttons-container">
                <button className="button" onClick={changeView}>Change View</button>
                <button className="button" onClick={calculateRoute}>Calculate Route</button>
            </div>
            <div id="map"></div>
        </div>
    );
};

export default Map;
